const payload = $json.body && typeof $json.body === 'object' ? $json.body : $json;

function cleanString(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value).trim();
}

function parseBudget(value) {
  if (value === undefined || value === null || value === '') {
    return 0;
  }

  const numericValue = Number(String(value).replace(/[^0-9.-]/g, ''));

  return Number.isFinite(numericValue) ? numericValue : 0;
}

const lead = {
  full_name: cleanString(payload.full_name),
  email: cleanString(payload.email).toLowerCase(),
  phone: cleanString(payload.phone),
  company: cleanString(payload.company),
  service_need: cleanString(payload.service_need),
  budget: parseBudget(payload.budget),
  urgency: cleanString(payload.urgency).toLowerCase(),
  message: cleanString(payload.message),
  source: cleanString(payload.source) || 'website_form',
};

const requiredFields = ['full_name', 'email', 'service_need', 'message'];

const missingRequiredFields = requiredFields.filter((field) => !lead[field]);

const validationErrors = [];

if (missingRequiredFields.length > 0) {
  validationErrors.push(`Missing required fields: ${missingRequiredFields.join(', ')}`);
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (lead.email && !emailPattern.test(lead.email)) {
  validationErrors.push('Email format is invalid');
}

const isValid = validationErrors.length === 0;

return {
  json: {
    received_at: new Date().toISOString(),
    validation_status: isValid ? 'valid' : 'invalid',
    is_valid: isValid,
    validation_errors: validationErrors,
    missing_required_fields: missingRequiredFields,
    lead,
    raw_payload: payload,
  },
};

const lead = $json.lead || {};
const validationStatus = $json.validation_status || 'invalid';
const isValid = $json.is_valid === true;

let leadScore = 0;
const scoringBreakdown = [];

function addScore(reason, points) {
  leadScore += points;
  scoringBreakdown.push({
    reason,
    points,
  });
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const hasValidEmail = typeof lead.email === 'string' && emailPattern.test(lead.email);

if (hasValidEmail) {
  addScore('Valid email present', 10);
}

if (lead.phone) {
  addScore('Phone present', 10);
}

if (lead.company) {
  addScore('Company present', 10);
}

const budget = Number(lead.budget) || 0;

if (budget >= 5000) {
  addScore('Budget is 5000 or higher', 30);
} else if (budget >= 1000) {
  addScore('Budget is between 1000 and 4999', 20);
} else {
  addScore('Budget is below 1000', 5);
}

const urgency = String(lead.urgency || '').toLowerCase();

if (urgency === 'urgent') {
  addScore('Urgency is urgent', 25);
} else if (urgency === 'high') {
  addScore('Urgency is high', 15);
}

const serviceNeed = String(lead.service_need || '').toLowerCase();
const priorityKeywords = ['automation', 'ai', 'workflow', 'integration', 'api'];

const matchedServiceKeywords = priorityKeywords.filter((keyword) =>
  serviceNeed.includes(keyword)
);

if (matchedServiceKeywords.length > 0) {
  addScore('Service need matches priority automation/API keywords', 20);
}

const message = String(lead.message || '');

if (message.length >= 80) {
  addScore('Message has at least 80 characters', 10);
}

let leadTier = 'incomplete';

if (isValid && leadScore >= 70) {
  leadTier = 'hot';
} else if (isValid && leadScore >= 45) {
  leadTier = 'qualified';
} else if (isValid && leadScore >= 25) {
  leadTier = 'nurture';
}

return {
  json: {
    ...$json,
    lead_score: leadScore,
    lead_tier: leadTier,
    scoring_breakdown: scoringBreakdown,
    matched_service_keywords: matchedServiceKeywords,
    scoring_status: isValid ? 'scored' : 'not_scored_invalid_lead',
    validation_status: validationStatus,
  },
};

const input = $json;

const lead = input.lead ?? input.normalized_lead ?? {};
const validationStatus = String(input.validation_status ?? '').toLowerCase();
const leadTier = String(input.lead_tier ?? '').toLowerCase();
const urgency = String(lead.urgency ?? input.urgency ?? '').toLowerCase();

let route = 'Manual Review';
let routeReason = 'Fallback route applied because no routing condition matched.';

if (validationStatus === 'invalid' || input.is_valid === false || leadTier === 'incomplete') {
  route = 'Manual Review';
  routeReason = 'Lead is invalid or incomplete and requires human review.';
} else if (urgency === 'urgent') {
  route = 'Urgent Human Review';
  routeReason = 'Lead marked as urgent and should be reviewed immediately.';
} else if (leadTier === 'hot') {
  route = 'Immediate Sales Follow-Up';
  routeReason = 'Lead score qualifies as hot and should receive immediate sales follow-up.';
} else if (leadTier === 'qualified') {
  route = 'Qualified Lead Queue';
  routeReason = 'Lead meets qualification threshold and should enter the qualified lead queue.';
} else if (leadTier === 'nurture') {
  route = 'Nurture Queue';
  routeReason = 'Lead has some value but is not ready for immediate sales follow-up.';
}

let responseStatus = 'success';

if (route === 'Manual Review' || route === 'Urgent Human Review') {
  responseStatus = 'needs_review';
}

return {
  json: {
    ...input,
    route,
    route_reason: routeReason,
    response_status: responseStatus,
    routing_status: 'routed',
  },
};

